vec3 result;
vec2 ab = b - a;
vec2 ac = c - a;
vec2 ap = p - a;

double denominator = ab.x * ac.y - ac.x * ab.y;
if (std::abs(denominator) < 1e-8) return vec3(-1, 1, 1);

double v = (ap.x * ac.y - ap.y * ac.x) / denominator;
double w = (ab.x * ap.y - ab.y * ap.x) / denominator;
double u = 1.0 - v - w;

result[0] = u;
result[1] = v;
result[2] = w;

return result;

